<?phpif (!defined('BASEPATH'))    exit('No direct script access allowed');class mwpgmodel extends CI_Model {    function fnGetWPGInfo($VarWPG='',$VarStatus='',$VarId='') {        $this->db->select('id,name,updatedby,type,status,datecreated,dateupdated'); // Select field        $this->db->from(KN_MASTER_FABRIC_FINISH);        if($VarStatus<>'') {            $this->db->where_in('status',array($VarStatus));        } else {            $this->db->where_in('status',array(1,2));        }        if($VarId<>'') {            $ArrWhere['id'] 				= $VarId;        }        if($VarWPG<>'') {            $ArrWhere['name'] 		    = $VarWPG;        }        if(@count($ArrWhere)>=1) {            $this->db->where($ArrWhere);        }        $ArrResultList	    	    		= $this->db->get()->result_array();        return $ArrResultList;    }    function fnCheckWPG($VarWPG='',$VarId='') {        $this->db->select('id,name,type,updatedby,status,datecreated,dateupdated');        $this->db->from(KN_MASTER_FABRIC_FINISH);        $ArrWhere = array('status'=>"1");        if($VarId<>'') {            $this->db->where_not_in('id',array($VarId));        }        if($VarWPG<>'') {            $ArrWhere['name']		= $VarWPG;        }        $this->db->where($ArrWhere);        $ObjResult  					= $this->db->get();        $ArrResultList					= $ObjResult->result_array();        return $ArrResultList;    }    function saveWPGInfo($ArrUpdateData){        $VarId                                                  = $ArrUpdateData['id'];        if($VarId=="") {            $ArrCheckExist			       					    = $this->fnGetWPGInfo($ArrUpdateData['name'],1);            if(@$ArrCheckExist['id']=='' && @$ArrCheckExist['id']==0) {                unset($ArrUpdateData['id']);                $this->db->insert(KN_MASTER_FABRIC_FINISH,$ArrUpdateData);                $VarId                                          = $this->db->insert_id();                $ArrResult['errcode']						    = 1;                $ArrResult['msg']							    = '';                $ArrResult['id']							    = $VarId;                $ArrResult['eid']							    = urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode']							= '-1';                $ArrResult['msg']								= "This wet processing greige name already exists!!";            }        } else {            $ArrCheckExist									    = $this->fnCheckWPG($ArrUpdateData['name'],$VarId);            if(@$ArrCheckExist['id']=='' && $ArrUpdateData['name']<>'') {                if($this->db->update(KN_MASTER_FABRIC_FINISH,$ArrUpdateData,array('id'=>$VarId))) {                    $ArrResult['errcode']					    = 1;                    $ArrResult['msg']							= '';                    $ArrResult['id']							= $VarId;                    $ArrResult['eid']							= urlencode(base64_encode($VarId));                } else {                    $ArrResult['errcode']						= '-1';                    $ArrResult['msg']							= 'Invalid Data!';                }            }  else {                $ArrResult['errcode']						    = '-1';                $ArrResult['msg']							    = "This wet processing greige name has already Exist!";            }        }        return $ArrResult;    }    function fnCountWPG($VarWPG='',$VarStatus='',$VarAfilter='') {        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $ArrWhere                   = array();        if($VarWPG<>'') {            $ArrWhere[]             = "wn.name like '%".$VarWPG."%'";        }        if($VarAfilter <> '') {            $ArrWhere[]             = "wn.name like '".$VarAfilter."%'";        }        if($VarStatus<>'') {            $ArrWhere[]             = "wn.status=".$VarStatus;        } else {            $ArrWhere[]             = "wn.status in(1,2)";        }        $VarWhere                   = '';        if(@$ArrWhere[0]<>'') {            $VarWhere               = implode(" and ",$ArrWhere) ." AND wn.companyid = ".$ArrUserLoggedInfo['companyid'];        }        $VarSqlWPG                  = "SELECT count(1) as trec  FROM ".KN_MASTER_FABRIC_FINISH." AS wn INNER JOIN ".KN_USERS." AS u ON wn.updatedby = u.id WHERE ".$VarWhere;        $ObjRows					= $this->db->query($VarSqlWPG)->row();        return $ObjRows->trec;    }    function fnListWPG($VarWPG='',$VarStatus='',$VarLimit = 10, $offset = 0,$VarSortBy,$VarSortOrder,$VarAfilter=''){        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $VarSortOrder				= ($VarSortOrder=='desc')? 'desc' : 'asc';        $VarSortCols				= array("1"=>'wn.name','2'=>'wn.status','3'=>'u.contactname','4'=>'dn.dateupdated');        $VarSortBy					= (in_array($VarSortBy,$VarSortCols)) ? $VarSortBy : 'wn.dateupdated';        $VarLimitInfo				= $VarLimit;        if($offset>=1) {$VarLimitInfo	 = $offset.",".$VarLimit;}        $ArrWhere                   = array();        if($VarWPG<>'') {            $ArrWhere[]             = "wn.name like '%".$VarWPG."%'";        }        if($VarAfilter <> '') {            $ArrWhere[]             = "wn.name like '".$VarAfilter."%'";        }        if($VarStatus<>'') {            $ArrWhere[]             = "wn.status=".$VarStatus;        } else {            $ArrWhere[]             = "wn.status in(1,2)";        }        $VarWhere                   = '';        if(@$ArrWhere[0]<>'') {            $VarWhere               = implode(" and ",$ArrWhere) ." AND wn.companyid = ".$ArrUserLoggedInfo['companyid'];        }        $VarSqlWPG          = "SELECT wn.id,wn.name,wn.type,u.contactname,wn.datecreated,wn.dateupdated,wn.status FROM ".KN_MASTER_FABRIC_FINISH." AS wn INNER JOIN ".KN_USERS." AS u ON wn.updatedby = u.id WHERE ".$VarWhere." order by ".$VarSortBy." ".$VarSortOrder." limit ".$VarLimitInfo;        $ObjResult					= $this->db->query($VarSqlWPG);        return $ObjResult;    }    function fnDelWPG($VarWPGId='',$VarUpdatedBy='') {        if(@$VarWPGId>=1) {            $ArrUpdateData          = array('status'=>3,'dateupdated'=>date('Y-m-d H:i:s'),'updatedby'=>$VarUpdatedBy);            if($this->db->update(KN_MASTER_FABRIC_FINISH,$ArrUpdateData,array('id'=>$VarWPGId))) {                $ArrResult['errcode']					    = 1;                $ArrResult['msg']							= '';                $ArrResult['id']							= $VarWPGId;                $ArrResult['eid']							= urlencode(base64_encode($VarWPGId));            } else {                $ArrResult['errcode']						= '-1';                $ArrResult['msg']							= 'Invalid Data!';            }        }        return $ArrResult;    }    function fnChangeComStat($checkboxids,$optvalue) {        $Arrids =  json_decode($checkboxids,true);        $this->db->where_in('id',$Arrids);        if($this->db->update(KN_MASTER_FABRIC_FINISH,array('status' => $optvalue))) {            return true;        }        return false;    }}